using GitSimEngine = VisualRelay.GitSim.GitSim;

namespace VisualRelay.Tests;

/// <summary>
/// A disposable clone of the <see cref="PipelineTestFixture"/> seed directory.
/// Each test gets its own clone — it owns the temp directory and the
/// in-memory <see cref="GitSimEngine"/> registered at that root, so a test
/// that mutates repo state (commit, archive, edit files) never touches the
/// shared seed or another test's clone.
/// </summary>
public sealed class PipelineClone : IDisposable
{
    public string Root { get; }
    public GitSimEngine Sim { get; }

    internal PipelineClone(string root, GitSimEngine sim)
    {
        Root = root;
        Sim = sim;
    }

    public void Dispose() => TestFileSystem.DeleteDirectoryResilient(Root);
}

using GitSimEngine = VisualRelay.GitSim.GitSim;

namespace VisualRelay.Tests;

public sealed partial class PipelineTestFixture
{
    /// <summary>
    /// Writes the standard pipeline shape into <paramref name="root"/> and
    /// seeds a GitSim repo with one commit, returning the seed commit sha.
    /// The caller must already have created the directory.
    /// </summary>
    internal static string SeedStandard(string root, GitSimEngine sim)
    {
        // Standard config: single test command, archiveOnDone:true.
        Directory.CreateDirectory(Path.Combine(root, ".relay"));
        File.WriteAllText(
            Path.Combine(root, ".relay", "config.json"),
            """
            {
              "testCmd": "test -f src/status.cs",
              "logSources": [],
              "baselineVerify": true,
              "enableFixVerify": false,
              "maxStageFailures": 3,
              "archiveOnDone": true,
              "tierProfiles": { "vision": "vision" }
            }
            """);

        // Standard task: ship-status with batch:2.
        Directory.CreateDirectory(Path.Combine(root, "llm-tasks"));
        File.WriteAllText(
            Path.Combine(root, "llm-tasks", "ship-status.md"),
            "batch: 2\n\n# Ship status\n");

        // Standard seed file: src/status.cs = "old".
        Directory.CreateDirectory(Path.Combine(root, "src"));
        File.WriteAllText(Path.Combine(root, "src", "status.cs"), "old");

        // Init GitSim, stage everything, commit.
        sim.InitRepo(root);
        sim.Git(root, "add", "-A").GetAwaiter().GetResult();
        return sim.Commit(root, "chore: seed repo");
    }
}

using GitSimEngine = VisualRelay.GitSim.GitSim;

namespace VisualRelay.Tests;

/// <summary>
/// Assembly-wide fixture that creates a single pre-seeded pipeline directory
/// once and provides a fast <see cref="Clone"/> for every test that needs the
/// standard pipeline shape (config: <c>test -f src/status.cs</c> /
/// archiveOnDone:true, task: ship-status / batch:2, seed: src/status.cs="old",
/// one GitSim commit).
///
/// <para>Tests that mutate the repo (RelayDriver commits, archives tasks,
/// edits files) call <see cref="Clone"/> to get their own disposable copy.
/// The seed directory is never written to after <see cref="InitializeAsync"/>.
/// </para>
/// </summary>
public sealed partial class PipelineTestFixture : IAsyncLifetime
{
    private string _seedRoot = null!;

    /// <summary>The seed directory root (read-only after initialization).</summary>
    public string SeedRoot => _seedRoot;

    /// <summary>
    /// Creates a disposable copy of the seed directory with a fresh GitSim
    /// engine registered at the clone root. Safe to call concurrently from
    /// parallel test collections: the seed is read-only after init and the
    /// copy is a pure directory-level operation.
    /// </summary>
    public PipelineClone Clone()
    {
        var cloneRoot = Path.Combine(Path.GetTempPath(), "visual-relay-tests", Guid.NewGuid().ToString("N"));
        CopyDirectoryRecursive(_seedRoot, cloneRoot);

        var sim = new GitSimEngine();
        sim.InitRepo(cloneRoot);
        sim.Git(cloneRoot, "add", "-A").GetAwaiter().GetResult();
        sim.Commit(cloneRoot, "chore: seed repo");

        return new PipelineClone(cloneRoot, sim);
    }

    Task IAsyncLifetime.InitializeAsync()
    {
        _seedRoot = Path.Combine(Path.GetTempPath(), "visual-relay-tests", Guid.NewGuid().ToString("N"));
        Directory.CreateDirectory(_seedRoot);
        SeedStandard(_seedRoot, new GitSimEngine());
        return Task.CompletedTask;
    }

    Task IAsyncLifetime.DisposeAsync()
    {
        TestFileSystem.DeleteDirectoryResilient(_seedRoot);
        return Task.CompletedTask;
    }

    private static void CopyDirectoryRecursive(string source, string dest)
    {
        Directory.CreateDirectory(dest);
        foreach (var entry in Directory.GetFileSystemEntries(source))
        {
            var destEntry = Path.Combine(dest, Path.GetFileName(entry));
            if (Directory.Exists(entry))
            {
                CopyDirectoryRecursive(entry, destEntry);
            }
            else
            {
                File.Copy(entry, destEntry);
            }
        }
    }
}

